"""Final evidence seal; excludes only generated bytecode and self-referential seals."""
import hashlib,json,subprocess
from pathlib import Path
P=Path(__file__).resolve().parent; ROOT=Path('/workspace')
auth=json.loads((P/'authorization.json').read_text())
paths=subprocess.check_output(['git','-c','safe.directory=/workspace','ls-files','--','apps/api/app','apps/api/config','apps/api/routes','apps/ai/app','contracts'],cwd=ROOT).decode().splitlines()
inventory=''.join(f'{hashlib.sha256((ROOT/p).read_bytes()).hexdigest()}  {p}\n' for p in sorted(paths))
assert hashlib.sha256(inventory.encode()).hexdigest()==auth['runtime']
assert inventory==(P/'preflight/runtime-source.sha256').read_text()
(P/'runtime-source-after.sha256').write_text(inventory)
assert json.loads((P/'capture-disabled.json').read_text())['capture_enabled'] is False
persistence=json.loads((P/'persistence.json').read_text())['items']
assert len(persistence)==3 and len({r['conversation_id'] for r in persistence})==3
for r in persistence:
    case=json.loads((P/'cases'/f"{r['item']}.json").read_text())
    assert r['question']==case['input']['utterance'] and r['status']==case['status']
    assert r['assistant_display_text']==case['displayed_text']
proof={'runtime_before':auth['runtime'],'runtime_after':hashlib.sha256(inventory.encode()).hexdigest(),
       'distinct_persisted_conversations':3,'one_user_turn_each':all(r['user_turns']==1 for r in persistence),
       'one_run_each':all(r['generation_runs']==1 for r in persistence),'displayed_text_matches_persistence':True,
       'capture_disabled_after':True,'prior_results_replaced':False,'main_unchanged':True}
assert subprocess.check_output(['git','-c','safe.directory=/workspace','rev-parse','main'],cwd=ROOT).decode().strip()==auth['main']
(P/'post-run-checks.json').write_text(json.dumps(proof,indent=2)+'\n')
files=sorted(p for p in P.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.suffix!='.pyc'
             and p.name not in ('checksums.sha256','aggregate.sha256','checksums-verification.txt'))
manifest=''.join(f'{hashlib.sha256(p.read_bytes()).hexdigest()}  {p.relative_to(P)}\n' for p in files)
(P/'checksums.sha256').write_text(manifest)
digest=hashlib.sha256(manifest.encode()).hexdigest()
(P/'aggregate.sha256').write_text(digest+'  checksums.sha256\n')
print(json.dumps({'files':len(files),'aggregate':digest,'post_run':proof},indent=2))
